#!/usr/bin/env node
// Bundle flow-trial-extension/core for the Outlook task pane (browser global).

const fs = require('fs');
const path = require('path');

const repo = path.join(__dirname, '..', '..');
const core = path.join(repo, 'flow-trial-extension', 'core');
const out = path.join(__dirname, '..', 'dist', 'core-bundle.js');

const files = [
  'domains.js',
  'day-words.js',
  'extract.js',
  'judgment.js',
  'google-closes.js',
  'close-families.js',
  'fact-reply.js',
  'file-attach.js',
  'draft-reply.js',
  'intent.js',
  'actions.js',
  'resolution.js',
  'system-notice.js',
  'incoming-judge.js'
].map((name) => path.join(core, name));

const header = [
  '// Generated by glance-outlook-addin/scripts/build-bundle.js',
  '// Do not edit. Re-run after core/ changes.',
  ''
].join('\n');

const footer = [
  '',
  'var GlanceOutlookEngine = {',
  '  judge: function (input) { return FlowIncomingJudge.judge(input || {}, {}); },',
  '  draftText: function (process, ctx) { return FlowIncomingJudge.draftText(process, ctx || {}); }',
  '};',
  ''
].join('\n');

const parts = files.map((file) => {
  return '// ----- ' + path.relative(repo, file) + ' -----\n' + fs.readFileSync(file, 'utf8').replace(/\s+$/, '') + '\n';
});

fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, header + parts.join('\n') + footer);
console.log('wrote ' + path.relative(repo, out));
